    VictoryRequirementText = "TEXT_COMMON_BATTLE_UI_VICTORY_CONDITION_TSMOD_CUT_FINAL_OLD",
    MapCfgGopId = "BATTLE_MAPCFG_MS21_X48_2"
  })
  pcall(function() BattleSetupTemplateInstance:OverrideSetting({MapCfgGopId = "BATTLE_MAPCFG_MS21_X48_2"}) end)
  -- No debug level-ups or placeholder dialogs from development builds.
  function ClassBattleBase:DebugChangeUnitMasterParameters_Implementation()
  end
