    g_ActiveAIUnitFunction = CallUnitAIFunc
  end
  BattleTemplateInstance:OverrideSetting({
    PostResultTransitionTarget = "/Game/Newera/Map/Story/ms21s_x48/ms21s_x48_part_battle_02"
  })
  -- The draft's Idore death event was only a placeholder popup; victory (Idore falls) is the draft's VictoryFunc.
  g_TriggerHPZeroTable = {}
  local lap = tsmod_cut_lap()
  local L = ({35, 50, 50})[lap]
  function ClassBattle:SpawnEnemyAndNeutralUnit_Implementation()
    local units = {
