      {"HOM2", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 8, 6, CHAR_DIR_EAST, 0},
      {"HOM3", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 11, 6, CHAR_DIR_EAST, 0},
      {"HOM4", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 14, 6, CHAR_DIR_EAST, 0},
      {"HOM5", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 17, 6, CHAR_DIR_EAST, 0},
      {"HOM6", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 20, 6, CHAR_DIR_EAST, 0},
      {"HOM7", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 5, 20, CHAR_DIR_WEST, 0},
      {"HOM8", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 8, 20, CHAR_DIR_WEST, 0},
      {"HOM9", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 11, 20, CHAR_DIR_WEST, 0},
      {"HOM10", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 14, 20, CHAR_DIR_WEST, 0},
      {"HOM11", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 17, 20, CHAR_DIR_WEST, 0},
      {"HOM12", "UNIT_MASTER_CH_M071", "BATTLE_UNITPARAM_CH_M071", 20, 20, CHAR_DIR_WEST, 0}
